from typing import Dict, Hashable, Sequence

State = Hashable
Record = Hashable


def channel_rate(states: Sequence[State], obs: Dict[State, Record]) -> int:
    """Rate r(obs) = number of distinct records the channel emits."""
    return len({obs[s] for s in states})

