function BALL_SIZE_BOUND(states, d, D):
    best <- 0
    for c in states:
        size <- count of s in states with d(c, s) <= D
        best <- max(best, size)
    return best

function RATE_DISTORTION_FLOOR(n, D):
    dim <- n * n
    total <- 2^dim
    B <- sum of C(dim, r) for r = 0..D
    return ceil(total / B)
